import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.zip.*;

/** Creates a portable .dcrbackup ZIP containing SQL data and the local certificate files. */
public class BackupRestoreFrame extends JInternalFrame {
    public BackupRestoreFrame(){setTitle("Backup & Restore");setSize(650,390);setDefaultCloseOperation(JInternalFrame.DISPOSE_ON_CLOSE);
        JPanel root=new JPanel(new BorderLayout(14,14));root.setBackground(AppTheme.BG);root.setBorder(new EmptyBorder(24,24,24,24));JPanel head=new JPanel(new GridLayout(2,1,0,5));head.setOpaque(false);head.add(AppTheme.title("Backup & Restore"));JLabel sub=new JLabel("Back up the MySQL records and the local certificates folder together");sub.setForeground(AppTheme.MUTED);head.add(sub);root.add(head,BorderLayout.NORTH);
        JPanel body=new JPanel(new GridLayout(2,1,0,12));body.setOpaque(false);body.add(infoCard("Create Backup","Export users, certificate metadata, activity logs and all files in certificates/ into one portable ZIP archive.","Create Backup",()->createBackup()));body.add(infoCard("Restore Backup","Restore a previously created .dcrbackup ZIP. This replaces current database records and may overwrite certificate files.","Choose Backup to Restore",()->restoreBackup()));root.add(body,BorderLayout.CENTER);
        JPanel bottom=new JPanel(new FlowLayout(FlowLayout.RIGHT));bottom.setOpaque(false);JButton close=AppTheme.button("← Back to Dashboard");bottom.add(close);root.add(bottom,BorderLayout.SOUTH);setContentPane(root);close.addActionListener(e->dispose());}
    private JPanel infoCard(String title,String description,String buttonText,Runnable action){JPanel p=AppTheme.card();JPanel t=new JPanel(new GridLayout(2,1,0,5));t.setOpaque(false);JLabel titleLabel=new JLabel(title);titleLabel.setFont(new Font("SansSerif",Font.BOLD,15));t.add(titleLabel);JLabel desc=new JLabel("<html><div style='width:420px'>"+description+"</div></html>");desc.setForeground(AppTheme.MUTED);t.add(desc);p.add(t,BorderLayout.CENTER);JButton b=AppTheme.primaryButton(buttonText);p.add(b,BorderLayout.EAST);b.addActionListener(e->action.run());return p;}

    private void createBackup(){JFileChooser chooser=new JFileChooser();chooser.setDialogTitle("Save repository backup");chooser.setSelectedFile(new File("digital-certificate-backup-"+java.time.LocalDate.now()+".dcrbackup"));chooser.setFileFilter(new FileNameExtensionFilter("DCR Backup (*.dcrbackup)","dcrbackup"));if(chooser.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;File out=chooser.getSelectedFile();if(!out.getName().toLowerCase().endsWith(".dcrbackup"))out=new File(out.getParentFile(),out.getName()+".dcrbackup");
        try{DatabaseSetup.ensureSchema();String dump=makeSqlDump();try(ZipOutputStream zip=new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(out)))){zip.putNextEntry(new ZipEntry("backup.sql"));zip.write(dump.getBytes(StandardCharsets.UTF_8));zip.closeEntry();Path certDir=Paths.get("certificates").toAbsolutePath().normalize();if(Files.exists(certDir)){try(java.util.stream.Stream<Path> paths=Files.walk(certDir)){paths.filter(Files::isRegularFile).forEach(path->{try{String rel=certDir.relativize(path).toString().replace(File.separatorChar,'/');zip.putNextEntry(new ZipEntry("certificates/"+rel));Files.copy(path,zip);zip.closeEntry();}catch(IOException ex){throw new UncheckedIOException(ex);}});}}}ActivityLogger.log("BACKUP_CREATED",out.getName());JOptionPane.showMessageDialog(this,"Backup created successfully:\n"+out.getAbsolutePath(),"Backup complete",JOptionPane.INFORMATION_MESSAGE);}catch(Exception ex){JOptionPane.showMessageDialog(this,"Could not create backup: "+rootMessage(ex),"Backup error",JOptionPane.ERROR_MESSAGE);}}

    private String makeSqlDump() throws SQLException {StringBuilder dump=new StringBuilder();String[] tables={"activity_logs","certificates","users"};try(Connection c=DatabaseConnection.getConnection();Statement s=c.createStatement()){for(String table:tables){dump.append("DELETE FROM `").append(table).append("`;\n");try(ResultSet r=s.executeQuery("SELECT * FROM `"+table+"`")){ResultSetMetaData md=r.getMetaData();int n=md.getColumnCount();while(r.next()){dump.append("INSERT INTO `").append(table).append("` (");for(int i=1;i<=n;i++){if(i>1)dump.append(',');dump.append('`').append(md.getColumnName(i)).append('`');}dump.append(") VALUES (");for(int i=1;i<=n;i++){if(i>1)dump.append(',');dump.append(sqlLiteral(r.getObject(i)));}dump.append(");\n");}}}}return dump.toString();}
    private String sqlLiteral(Object value){if(value==null)return "NULL";if(value instanceof Number)return value.toString();String s=value.toString().replace("\\","\\\\").replace("'","''").replace("\u0000","");return "'"+s+"'";}

    private void restoreBackup(){JFileChooser chooser=new JFileChooser();chooser.setDialogTitle("Select DCR backup");chooser.setFileFilter(new FileNameExtensionFilter("DCR Backup (*.dcrbackup)","dcrbackup"));if(chooser.showOpenDialog(this)!=JFileChooser.APPROVE_OPTION)return;File in=chooser.getSelectedFile();int answer=JOptionPane.showConfirmDialog(this,"Restore this backup? Current users, certificates and activity logs will be replaced. Certificate files with matching names may be overwritten.","Confirm restore",JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE);if(answer!=JOptionPane.YES_OPTION)return;
        Path stage=null;try{DatabaseSetup.ensureSchema();stage=Files.createTempDirectory("dcr-restore-");String sql=null;try(ZipInputStream zip=new ZipInputStream(new BufferedInputStream(new FileInputStream(in)))){ZipEntry e;while((e=zip.getNextEntry())!=null){Path dest=stage.resolve(e.getName()).normalize();if(!dest.startsWith(stage))throw new IOException("Backup contains an unsafe file path.");if(e.isDirectory()){Files.createDirectories(dest);}else{Files.createDirectories(dest.getParent());Files.copy(zip,dest,StandardCopyOption.REPLACE_EXISTING);}zip.closeEntry();}}Path sqlFile=stage.resolve("backup.sql");if(!Files.exists(sqlFile))throw new IOException("This ZIP does not contain backup.sql and is not a valid DCR backup.");sql=Files.readString(sqlFile,StandardCharsets.UTF_8);runRestoreSql(sql);
            Path stagedCert=stage.resolve("certificates");if(Files.exists(stagedCert)){Path dest=Paths.get("certificates").toAbsolutePath().normalize();Files.createDirectories(dest);try(java.util.stream.Stream<Path> paths=Files.walk(stagedCert)){paths.filter(Files::isRegularFile).forEach(path->{try{Path target=dest.resolve(stagedCert.relativize(path)).normalize();if(!target.startsWith(dest))throw new IOException("Unsafe certificate path.");Files.createDirectories(target.getParent());Files.copy(path,target,StandardCopyOption.REPLACE_EXISTING);}catch(IOException ex){throw new UncheckedIOException(ex);}});}}
            ActivityLogger.log("BACKUP_RESTORED",in.getName());JOptionPane.showMessageDialog(this,"Backup restored. Close and reopen the dashboard to refresh all views.","Restore complete",JOptionPane.INFORMATION_MESSAGE);
        }catch(Exception ex){JOptionPane.showMessageDialog(this,"Could not restore backup: "+rootMessage(ex),"Restore error",JOptionPane.ERROR_MESSAGE);}finally{if(stage!=null)try{deleteTree(stage);}catch(IOException ignored){}}}

    private void runRestoreSql(String sql) throws SQLException {List<String> statements=splitSql(sql);try(Connection c=DatabaseConnection.getConnection()){boolean old=c.getAutoCommit();c.setAutoCommit(false);try(Statement s=c.createStatement()){for(String statement:statements){String trimmed=statement.trim();if(trimmed.isEmpty()||trimmed.startsWith("--"))continue;s.executeUpdate(trimmed);}c.commit();}catch(SQLException ex){c.rollback();throw ex;}finally{c.setAutoCommit(old);}}}
    private List<String> splitSql(String sql){List<String> result=new ArrayList<>();StringBuilder current=new StringBuilder();boolean quoted=false,escaped=false;for(int i=0;i<sql.length();i++){char ch=sql.charAt(i);if(escaped){current.append(ch);escaped=false;continue;}if(ch=='\\'&&quoted){current.append(ch);escaped=true;continue;}if(ch=='\''){current.append(ch);if(quoted&&i+1<sql.length()&&sql.charAt(i+1)=='\''){current.append(sql.charAt(++i));continue;}quoted=!quoted;continue;}if(ch==';'&&!quoted){result.add(current.toString());current.setLength(0);}else current.append(ch);}if(!current.toString().trim().isEmpty())result.add(current.toString());return result;}
    private static String rootMessage(Throwable ex){Throwable t=ex;while(t.getCause()!=null)t=t.getCause();return t.getMessage()==null?t.toString():t.getMessage();}
    private static void deleteTree(Path root)throws IOException{if(!Files.exists(root))return;try(java.util.stream.Stream<Path> paths=Files.walk(root)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(IOException ignored){}});}}
}
